"use client";

import * as React from "react";
import styles from "../styles/avatar-group.module.css";

export interface AvatarGroupProps {
  /** People shown in the stack (initials are derived from each name) */
  names?: string[];
  /** Maximum avatars shown before collapsing the rest into a +N chip */
  max?: number;
  /** Avatar size preset */
  size?: "sm" | "md" | "lg";
  /** How much neighbouring avatars overlap, as a fraction of the avatar size (0–0.6) */
  overlap?: number;
  /** Fan the stack apart while the group is hovered or focused */
  spreadOnHover?: boolean;
  /** Show a deterministic presence dot (online / away / busy / offline) on each avatar */
  showStatus?: boolean;
  /** Show the person's name in a small tooltip on hover / focus */
  showTooltip?: boolean;
  /** Accent color used by the +N chip and focus tint */
  accentColor?: string;
  /** Accessible name of the group */
  label?: string;
  /** Called when the +N chip toggles the full list */
  onExpandedChange?: (expanded: boolean) => void;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_NAMES = [
  "Ava Thompson",
  "Liam Chen",
  "Sofia Martinez",
  "Noah Patel",
  "Maya Okafor",
  "Ethan Brooks",
  "Isla Novak",
  "Kai Tanaka",
  "Zara Ahmed",
];

const STATUSES = ["online", "away", "online", "busy", "offline", "online", "away", "online", "busy"] as const;

function hash(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function initials(name: string) {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  const first = parts[0]?.[0] ?? "";
  const last = parts.length > 1 ? parts[parts.length - 1]?.[0] ?? "" : parts[0]?.[1] ?? "";
  return (first + last).toUpperCase();
}

function gradientFor(name: string) {
  const h = hash(name);
  const hue = h % 360;
  const hue2 = (hue + 35 + ((h >>> 9) % 50)) % 360;
  const angle = 120 + ((h >>> 3) % 120);
  return `linear-gradient(${angle}deg, hsl(${hue} 78% 62%), hsl(${hue2} 72% 46%))`;
}

export function AvatarGroup({
  names = DEFAULT_NAMES,
  max = 5,
  size = "md",
  overlap = 0.3,
  spreadOnHover = true,
  showStatus = true,
  showTooltip = true,
  accentColor = "#6366f1",
  label = "Project members",
  onExpandedChange,
  className = "",
  style,
}: AvatarGroupProps) {
  const [expanded, setExpanded] = React.useState(false);
  const limit = Math.max(1, Math.floor(max));
  const visible = expanded ? names : names.slice(0, limit);
  const hidden = names.length - visible.length;
  const ov = Math.min(0.6, Math.max(0, overlap));

  const toggle = () => {
    const next = !expanded;
    setExpanded(next);
    onExpandedChange?.(next);
  };

  return (
    <div
      role="group"
      aria-label={label}
      className={`${styles.root} ${className}`.trim()}
      data-size={size}
      data-spread={spreadOnHover ? "" : undefined}
      style={{ "--mf-ag-accent": accentColor, "--mf-ag-overlap": ov, ...style } as React.CSSProperties}
    >
      <ul className={styles.list}>
        {visible.map((name, i) => {
          const status = STATUSES[i % STATUSES.length] ?? "online";
          const desc = showStatus ? `${name} (${status})` : name;
          return (
            <li key={`${name}-${i}`} className={styles.item} style={{ "--mf-ag-i": i, zIndex: visible.length - i } as React.CSSProperties}>
              <span role="img" aria-label={desc} tabIndex={0} className={styles.avatar} style={{ backgroundImage: gradientFor(name) }}>
                <span aria-hidden="true" className={styles.initials}>
                  {initials(name)}
                </span>
                {showStatus && <span aria-hidden="true" className={styles.status} data-status={status} />}
              </span>
              {showTooltip && (
                <span aria-hidden="true" className={styles.tip}>
                  {name}
                </span>
              )}
            </li>
          );
        })}
        {(hidden > 0 || expanded) && names.length > limit && (
          <li className={styles.item} style={{ "--mf-ag-i": visible.length, zIndex: 0 } as React.CSSProperties}>
            <button
              type="button"
              className={`${styles.avatar} ${styles.more}`}
              aria-expanded={expanded}
              aria-label={expanded ? "Show fewer members" : `Show ${hidden} more: ${names.slice(limit).join(", ")}`}
              onClick={toggle}
            >
              {expanded ? (
                <svg aria-hidden="true" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
                  <path d="M15 6l-6 6 6 6" />
                </svg>
              ) : (
                `+${hidden}`
              )}
            </button>
          </li>
        )}
      </ul>
    </div>
  );
}

.root {
  --mf-ag-size: 2.5rem;
  --mf-ag-fs: 0.875rem;
  --mf-ag-ring: var(--mf-bg, #0b0b0f);
  display: inline-flex;
  align-items: center;
  color: var(--mf-fg, #f4f4f6);
}

.root[data-size="sm"] {
  --mf-ag-size: 2rem;
  --mf-ag-fs: 0.75rem;
}

.root[data-size="lg"] {
  --mf-ag-size: 3.25rem;
  --mf-ag-fs: 1.0625rem;
}

.list {
  display: flex;
  align-items: center;
  margin: 0;
  padding: 0.375rem 0;
  list-style: none;
}

.item {
  position: relative;
  margin-left: calc(var(--mf-ag-size) * var(--mf-ag-overlap, 0.3) * -1);
  transition: margin-left 260ms cubic-bezier(0.16, 1, 0.3, 1);
  animation: mf-ag-in 420ms cubic-bezier(0.16, 1, 0.3, 1) both;
  animation-delay: calc(var(--mf-ag-i, 0) * 55ms);
}

.item:first-child {
  margin-left: 0;
}

.root[data-spread]:hover .item:not(:first-child),
.root[data-spread]:focus-within .item:not(:first-child) {
  margin-left: 0.25rem;
}

.avatar {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--mf-ag-size);
  height: var(--mf-ag-size);
  border-radius: 999px;
  background-color: var(--mf-surface-raised, #1b1b22);
  background-size: cover;
  box-shadow: 0 0 0 2px var(--mf-ag-ring);
  color: #fff;
  font-size: var(--mf-ag-fs);
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: default;
  user-select: none;
  transition: transform 220ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 200ms ease;
}

.initials {
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
}

.item:hover .avatar,
.avatar:focus-visible {
  transform: translateY(-4px) scale(1.06);
}

.item:hover,
.item:focus-within {
  z-index: 50 !important;
}

.avatar:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 2px;
}

.status {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 28%;
  height: 28%;
  min-width: 0.5rem;
  min-height: 0.5rem;
  border-radius: 999px;
  border: 2px solid var(--mf-ag-ring);
  background-color: #22c55e;
}

.status[data-status="away"] {
  background-color: #f59e0b;
}

.status[data-status="busy"] {
  background-color: #ef4444;
}

.status[data-status="offline"] {
  background-color: var(--mf-subtle, #71717a);
}

.status[data-status="online"]::after {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: inherit;
  border: 2px solid #22c55e;
  animation: mf-ag-ping 2.2s cubic-bezier(0, 0, 0.2, 1) infinite;
}

.more {
  border: 1px solid color-mix(in srgb, var(--mf-ag-accent, #6366f1) 45%, var(--mf-border, #2e2e38));
  background-color: color-mix(in srgb, var(--mf-ag-accent, #6366f1) 16%, var(--mf-surface, #141419));
  color: var(--mf-fg, #f4f4f6);
  font: inherit;
  font-size: calc(var(--mf-ag-fs) * 0.92);
  font-weight: 600;
  cursor: pointer;
}

.more:hover {
  background-color: color-mix(in srgb, var(--mf-ag-accent, #6366f1) 28%, var(--mf-surface, #141419));
}

.tip {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 0.5rem);
  padding: 0.25rem 0.5rem;
  border-radius: 0.375rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface-raised, #1b1b22);
  color: var(--mf-fg, #f4f4f6);
  font-size: 0.75rem;
  font-weight: 500;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transform: translate(-50%, 4px);
  transition: opacity 150ms ease, transform 180ms cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.25);
}

.item:hover .tip,
.item:focus-within .tip {
  opacity: 1;
  transform: translate(-50%, 0);
}

@keyframes mf-ag-in {
  from {
    opacity: 0;
    transform: translateX(-8px) scale(0.85);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes mf-ag-ping {
  0% {
    opacity: 0.7;
    transform: scale(1);
  }
  80%,
  100% {
    opacity: 0;
    transform: scale(2);
  }
}

@media (prefers-reduced-motion: reduce) {
  .item,
  .avatar,
  .tip {
    transition: none;
    animation: none;
  }
  .status::after {
    animation: none;
    display: none;
  }
  .item:hover .avatar,
  .avatar:focus-visible {
    transform: none;
  }
}

