"use client";

const people = ["Ava Thompson", "Liam Chen", "Sofia Martinez", "Noah Patel", "Maya Okafor", "Ethan Brooks", "Isla Novak"];
const hues = [262, 199, 330, 150, 24, 220, 290];

export function AvatarGroupTailwind({ max = 5 }) {
  const shown = people.slice(0, max);
  return (
    <div role="group" aria-label="Project members" className="group flex items-center">
      {shown.map((n, i) => (
        <span key={n} role="img" aria-label={n} tabIndex={0} style={{ backgroundImage: `linear-gradient(135deg, hsl(${hues[i]} 78% 62%), hsl(${hues[i] + 40} 72% 46%))` }} className="relative -ml-3 grid size-10 place-items-center rounded-full text-sm font-semibold text-white ring-2 ring-zinc-950 transition-all duration-300 first:ml-0 group-hover:ml-1 first:group-hover:ml-0 hover:z-10 hover:-translate-y-1 hover:scale-105">
          {n.split(" ").map((p) => p[0]).join("")}
          <span aria-hidden className="absolute bottom-0 right-0 size-2.5 rounded-full bg-emerald-500 ring-2 ring-zinc-950" />
        </span>
      ))}
      {people.length > max && (
        <button type="button" aria-label={`${people.length - max} more`} className="-ml-3 grid size-10 place-items-center rounded-full border border-indigo-500/50 bg-indigo-500/15 text-sm font-semibold text-zinc-100 ring-2 ring-zinc-950 transition-all group-hover:ml-1">+{people.length - max}</button>
      )}
    </div>
  );
}
